import { useState, useEffect, useCallback, useRef } from 'react';
import { fetchAlarms, acknowledgeAlarm } from '../api/gateway';

const DEMO_ALARMS = [
  {
    id: 'alm-1',
    machine_id: 'refinery-1',
    severity: 'medium',
    message: 'Heater unit core temp fluctuation detected (+12°C)',
    raised_at: new Date(Date.now() - 6 * 60 * 1000).toISOString(),
    status: 'active',
  },
  {
    id: 'alm-2',
    machine_id: 'refinery-2',
    severity: 'low',
    message: 'Flow pump valve calibration advisory',
    raised_at: new Date(Date.now() - 14 * 60 * 1000).toISOString(),
    status: 'active',
  },
];

export function useAlarms() {
  const [alarms, setAlarms] = useState(DEMO_ALARMS);
  const [loading, setLoading] = useState(true);
  const isDemoRef = useRef(false);

  const load = useCallback(async () => {
    try {
      const data = await fetchAlarms();
      const list = Array.isArray(data) ? data : data.items || data.alarms || [];
      if (list.length > 0) {
        setAlarms(list);
        isDemoRef.current = false;
      }
    } catch (_) {
      isDemoRef.current = true;
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
    const id = setInterval(load, 5000);
    return () => clearInterval(id);
  }, [load]);

  const acknowledge = useCallback(async (alarmId, note = '') => {
    try {
      await acknowledgeAlarm(alarmId, note);
      load();
    } catch (_) {
      // Demo mode fallback: update local state directly
      setAlarms(prev =>
        prev.map(a => a.id === alarmId ? { ...a, status: 'acknowledged' } : a)
      );
    }
  }, [load]);

  return { alarms, loading, acknowledge, refresh: load };
}
