import React, { useState } from 'react';

export default function SetpointInput({
  label, unit, min, max, step = 1, disabled, onChange,
}) {
  const [raw, setRaw] = useState('');

  const num         = raw === '' ? NaN : Number(raw);
  const outOfRange  = !isNaN(num) && (num < min || num > max);
  const canSubmit   = raw !== '' && !isNaN(num) && !outOfRange && !disabled;

  const handleSubmit = () => {
    if (!canSubmit) return;
    onChange && onChange(num);
    setRaw('');
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '7px' }}>
      <label style={{
        fontFamily:    "'Share Tech Mono', monospace",
        fontSize:      '10px',
        color:         'var(--text-muted)',
        letterSpacing: '0.08em',
        textTransform: 'uppercase',
      }}>
        {label}
      </label>

      <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
        <input
          id={`sp-input-${label}`}
          type="number"
          value={raw}
          min={min}
          max={max}
          step={step}
          disabled={disabled}
          placeholder={`${min}–${max}`}
          onChange={e => setRaw(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && handleSubmit()}
          style={{
            background:   'rgba(0, 12, 36, 0.85)',
            border:       `1px solid ${outOfRange ? 'var(--danger)' : 'rgba(0,212,255,0.28)'}`,
            borderRadius: '6px',
            color:        outOfRange ? 'var(--danger)' : 'var(--cyan)',
            fontFamily:   "'Share Tech Mono', monospace",
            fontSize:     '16px',
            padding:      '8px 12px',
            width:        '110px',
            outline:      'none',
            transition:   'border-color 200ms',
            opacity:      disabled ? 0.4 : 1,
            cursor:       disabled ? 'not-allowed' : 'text',
          }}
        />
        <span style={{
          fontFamily: "'Share Tech Mono', monospace",
          fontSize:   '12px',
          color:      'var(--text-muted)',
          minWidth:   '36px',
        }}>
          {unit}
        </span>
        <button
          onClick={handleSubmit}
          disabled={!canSubmit}
          style={{
            background:    canSubmit ? 'rgba(0,212,255,0.1)' : 'transparent',
            border:        `1px solid ${canSubmit ? 'rgba(0,212,255,0.45)' : 'rgba(0,212,255,0.12)'}`,
            borderRadius:  '6px',
            color:         canSubmit ? 'var(--cyan)' : 'var(--text-muted)',
            fontFamily:    "'Share Tech Mono', monospace",
            fontSize:      '12px',
            padding:       '8px 14px',
            cursor:        canSubmit ? 'pointer' : 'not-allowed',
            letterSpacing: '0.06em',
            transition:    'all 200ms',
          }}
        >
          SET
        </button>
      </div>

      <div style={{
        fontFamily:    "'Share Tech Mono', monospace",
        fontSize:      '10px',
        color:         outOfRange ? 'var(--danger)' : 'var(--text-muted)',
        letterSpacing: '0.05em',
      }}>
        {outOfRange
          ? `OUT OF RANGE — VALID: ${min}–${max} ${unit}`
          : `RANGE: ${min} – ${max} ${unit}`}
      </div>
    </div>
  );
}
