import React, { useState } from 'react';
import { AlertOctagon, X, RotateCcw } from 'lucide-react';

export default function EmergencyStop({ machineId, disabled, isStopped, onTrigger }) {
  const [armed, setArmed] = useState(false);

  // If machine is currently stopped, provide direct Reset / Re-Starting button
  if (isStopped) {
    return (
      <div style={{
        padding:      '14px',
        background:   'rgba(255, 51, 102, 0.08)',
        border:       '1px solid rgba(255, 51, 102, 0.4)',
        borderRadius: '8px',
        display:      'flex',
        flexDirection: 'column',
        gap:          '10px',
      }}>
        <div style={{
          fontFamily:    "'Share Tech Mono', monospace",
          fontSize:      '11px',
          color:         'var(--danger)',
          textAlign:     'center',
          letterSpacing: '0.08em',
        }}>
          ⚠ MACHINE EMERGENCY STOPPED
        </div>
        <button
          id={`estop-reset-${machineId}`}
          onClick={() => {
            if (!disabled && onTrigger) {
              onTrigger('reset_emergency_stop', null, 'Operator cleared emergency shutdown');
            }
          }}
          disabled={disabled}
          style={{
            display:        'flex',
            alignItems:     'center',
            justifyContent: 'center',
            gap:            '8px',
            width:          '100%',
            padding:        '12px',
            background:     'rgba(0, 230, 118, 0.15)',
            border:         '1px solid #00e676',
            borderRadius:   '6px',
            color:          '#00e676',
            cursor:         disabled ? 'not-allowed' : 'pointer',
            fontFamily:     "'Rajdhani', sans-serif",
            fontWeight:     700,
            fontSize:       '14px',
            letterSpacing:  '0.12em',
            boxShadow:      '0 0 16px rgba(0, 230, 118, 0.25)',
            transition:     'all 200ms',
            opacity:        disabled ? 0.4 : 1,
          }}
        >
          <RotateCcw size={15} />
          RESET EMERGENCY STOP / RESUME
        </button>
      </div>
    );
  }

  if (!armed) {
    return (
      <button
        id={`estop-arm-${machineId}`}
        onClick={() => !disabled && setArmed(true)}
        disabled={disabled}
        style={{
          display:        'flex',
          alignItems:     'center',
          justifyContent: 'center',
          gap:            '8px',
          width:          '100%',
          padding:        '10px 14px',
          background:     'rgba(255, 51, 102, 0.04)',
          border:         '1px dashed rgba(255, 51, 102, 0.28)',
          borderRadius:   '8px',
          color:          'rgba(255,51,102,0.55)',
          cursor:         disabled ? 'not-allowed' : 'pointer',
          fontFamily:     "'Share Tech Mono', monospace",
          fontSize:       '12px',
          letterSpacing:  '0.1em',
          opacity:        disabled ? 0.4 : 1,
          transition:     'all 200ms',
        }}
        onMouseEnter={e => { if (!disabled) { e.currentTarget.style.borderColor = 'rgba(255,51,102,0.55)'; e.currentTarget.style.color = '#ff3366'; } }}
        onMouseLeave={e => { e.currentTarget.style.borderColor = 'rgba(255,51,102,0.28)'; e.currentTarget.style.color = 'rgba(255,51,102,0.55)'; }}
      >
        <AlertOctagon size={14} />
        ARM EMERGENCY STOP
      </button>
    );
  }

  return (
    <div style={{
      padding:      '14px',
      background:   'rgba(255, 51, 102, 0.07)',
      border:       '1px solid rgba(255, 51, 102, 0.4)',
      borderRadius: '8px',
      animation:    'danger-glow-pulse 1.5s ease-in-out infinite',
    }}>
      <div style={{
        fontFamily:    "'Share Tech Mono', monospace",
        fontSize:      '11px',
        color:         'var(--danger)',
        textAlign:     'center',
        letterSpacing: '0.1em',
        marginBottom:  '12px',
      }}>
        ⚠ E-STOP ARMED — CONFIRM TO EXECUTE
      </div>
      <div style={{ display: 'flex', gap: '8px' }}>
        <button
          id={`estop-confirm-${machineId}`}
          onClick={() => {
            onTrigger && onTrigger('emergency_stop', null, 'Manual emergency stop triggered from HMI');
            setArmed(false);
          }}
          style={{
            flex:          1,
            padding:       '11px',
            background:    'rgba(255, 51, 102, 0.18)',
            border:        '1px solid var(--danger)',
            borderRadius:  '6px',
            color:         'var(--danger)',
            cursor:        'pointer',
            fontFamily:    "'Rajdhani', sans-serif",
            fontWeight:    700,
            fontSize:      '15px',
            letterSpacing: '0.12em',
            boxShadow:     '0 0 16px rgba(255,51,102,0.3)',
          }}
        >
          ⚠ E-STOP
        </button>
        <button
          onClick={() => setArmed(false)}
          style={{
            padding:       '11px 16px',
            background:    'transparent',
            border:        '1px solid rgba(120,168,204,0.28)',
            borderRadius:  '6px',
            color:         'var(--text-muted)',
            cursor:        'pointer',
            fontFamily:    "'Share Tech Mono', monospace",
            fontSize:      '12px',
            display:       'flex',
            alignItems:    'center',
            gap:           '4px',
          }}
        >
          <X size={13} /> CANCEL
        </button>
      </div>
    </div>
  );
}

