import { useState, useEffect } from 'react';
import { fetchHistory } from '../api/gateway';

function generateSimHistory(metric) {
  const now = Date.now();
  const samples = [];
  let base = metric === 'temperature' ? 340 : metric === 'pressure' ? 4.2 : 125;
  const variance = metric === 'temperature' ? 6 : metric === 'pressure' ? 0.2 : 5;

  for (let i = 24; i >= 0; i--) {
    const timestamp = new Date(now - i * 60 * 1000).toISOString();
    base = base + (Math.random() - 0.48) * variance;
    const value = parseFloat(base.toFixed(2));
    samples.push({ timestamp, value });
  }
  return samples;
}

export function useHistory(machineId, metric) {
  const [samples, setSamples] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!machineId || !metric) return;
    setLoading(true);
    setError(null);
    const to = new Date().toISOString();
    const from = new Date(Date.now() - 30 * 60 * 1000).toISOString();
    fetchHistory(machineId, metric, from, to)
      .then(data => {
        if (data && data.samples && data.samples.length > 0) {
          setSamples(data.samples);
        } else {
          setSamples(generateSimHistory(metric));
        }
        setLoading(false);
      })
      .catch(() => {
        // Fall back to demo simulation history
        setSamples(generateSimHistory(metric));
        setLoading(false);
      });
  }, [machineId, metric]);

  return { samples, loading, error };
}
