import React from 'react';

export function getMachineStatus(machineTelemetry) {
  if (!machineTelemetry) {
    return { label: 'OFFLINE', color: 'gray', status: 'offline' };
  }
  if (machineTelemetry.emergency_stopped || machineTelemetry.status === 'stopped') {
    return { label: 'STOPPED', color: 'red', status: 'stopped' };
  }
  if (machineTelemetry.status === 'offline') {
    return { label: 'OFFLINE', color: 'gray', status: 'offline' };
  }
  return { label: 'OPERATIONAL', color: 'green', status: 'operational' };
}

const STATUS_CONFIG = {
  // Operational (Green)
  operational: { label: 'OPERATIONAL', color: '#00e676', glow: 'rgba(0,230,118,0.4)' },
  green:       { label: 'OPERATIONAL', color: '#00e676', glow: 'rgba(0,230,118,0.4)' },
  online:      { label: 'OPERATIONAL', color: '#00e676', glow: 'rgba(0,230,118,0.4)' },
  connected:   { label: 'CONNECTED',   color: '#00d4ff', glow: 'rgba(0,212,255,0.4)' },
  ok:          { label: 'OK',          color: '#00e676', glow: 'rgba(0,230,118,0.4)' },
  healthy:     { label: 'HEALTHY',     color: '#00e676', glow: 'rgba(0,230,118,0.4)' },
  applied:     { label: 'APPLIED',     color: '#00d4ff', glow: 'rgba(0,212,255,0.4)' },
  nominal:     { label: 'NOMINAL',     color: '#00e676', glow: 'rgba(0,230,118,0.4)' },

  // Abnormal / warning / pending (Yellow)
  warning:     { label: 'WARNING',     color: '#ffd700', glow: 'rgba(255,215,0,0.4)' },
  pending:     { label: 'PENDING',     color: '#ffd700', glow: 'rgba(255,215,0,0.4)' },
  degraded:    { label: 'DEGRADED',    color: '#ffd700', glow: 'rgba(255,215,0,0.4)' },
  abnormal:    { label: 'ABNORMAL',    color: '#ffd700', glow: 'rgba(255,215,0,0.4)' },
  error:       { label: 'ERROR',       color: '#ffd700', glow: 'rgba(255,215,0,0.4)' },

  // Stopped / Critical / Offline (Red / Gray)
  stopped:           { label: 'STOPPED',   color: '#ff3366', glow: 'rgba(255,51,102,0.4)' },
  emergency_stopped: { label: 'STOPPED',   color: '#ff3366', glow: 'rgba(255,51,102,0.4)' },
  red:               { label: 'STOPPED',   color: '#ff3366', glow: 'rgba(255,51,102,0.4)' },
  offline:           { label: 'OFFLINE',   color: '#8899aa', glow: 'rgba(136,153,170,0.3)' },
  gray:              { label: 'OFFLINE',   color: '#8899aa', glow: 'rgba(136,153,170,0.3)' },
  critical:          { label: 'CRITICAL',  color: '#ff3366', glow: 'rgba(255,51,102,0.4)' },
  severe:            { label: 'SEVERE',    color: '#ff3366', glow: 'rgba(255,51,102,0.4)' },
  fault:             { label: 'FAULT',     color: '#ff3366', glow: 'rgba(255,51,102,0.4)' },
  rejected:          { label: 'REJECTED',  color: '#ff3366', glow: 'rgba(255,51,102,0.4)' },

  unknown:           { label: 'UNKNOWN',   color: '#78a8cc', glow: 'rgba(120,168,204,0.3)' },
};

const SIZES = {
  sm: { fontSize: '10px', padding: '2px 7px', dot: '6px' },
  md: { fontSize: '11px', padding: '3px 9px', dot: '7px' },
  lg: { fontSize: '13px', padding: '5px 11px', dot: '8px' },
};

export default function StatusBadge({ status, label, size = 'md' }) {
  const key   = (status || 'unknown').toLowerCase();
  const cfg   = STATUS_CONFIG[key] || STATUS_CONFIG.unknown;
  const txt   = label || cfg.label;
  const s     = SIZES[size] || SIZES.md;

  return (
    <span style={{
      display:        'inline-flex',
      alignItems:     'center',
      gap:            '5px',
      background:     `${cfg.glow}22`,
      border:         `1px solid ${cfg.color}44`,
      borderRadius:   '3px',
      padding:        s.padding,
      fontSize:       s.fontSize,
      fontFamily:     "'Share Tech Mono', monospace",
      color:          cfg.color,
      letterSpacing:  '0.08em',
      textShadow:     `0 0 8px ${cfg.glow}`,
      whiteSpace:     'nowrap',
    }}>
      <span style={{
        width:        s.dot,
        height:       s.dot,
        borderRadius: '50%',
        background:   cfg.color,
        boxShadow:    `0 0 6px ${cfg.color}`,
        flexShrink:   0,
      }} />
      {txt}
    </span>
  );
}
