import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { X, Activity, Settings, Clock, FileText, Sliders, ToggleLeft, PlayCircle, ShieldAlert } from 'lucide-react';
import MachineHealth from './MachineHealth';
import { getMachineStatus } from '../shared/StatusBadge';
import TrendChart from './TrendChart';
import ControlAuditList from './ControlAuditList';
import ControlKnob from '../controls/ControlKnob';
import SetpointInput from '../controls/SetpointInput';
import ToggleControl from '../controls/ToggleControl';
import ModeSelectorControl from '../controls/ModeSelectorControl';
import ActionTriggerControl from '../controls/ActionTriggerControl';
import EmergencyStop from '../controls/EmergencyStop';
import CommandConfirmDialog from '../controls/CommandConfirmDialog';
import { useCommand } from '../../hooks/useCommand';

/* ── Per-machine control definitions ──────────────────────────────────────── */
const MACHINE_CFG = {
  'refinery-1': {
    title:   'HEATER & REACTOR UNIT',
    color:   '#00d4ff',
    dataKey: 'refinery-1',
    modes: [
      { id: 'AUTO_PID', label: 'AUTO PID' },
      { id: 'MANUAL',   label: 'MANUAL'   },
      { id: 'STANDBY',  label: 'STANDBY'  },
    ],
    knobs: [
      { id: 'set_temperature',       label: 'Temp Setpoint',       unit: '°C',   min: 150.0, max: 220.0, step: 0.5, defaultVal: 175.0 },
      { id: 'pressure_limit',        label: 'Pressure Threshold',  unit: 'bar',  min: 5,     max: 50,    step: 1,   defaultVal: 28    },
      { id: 'exhaust_fan_speed',     label: 'Exhaust Fan Speed',   unit: '%',    min: 0,     max: 100,   step: 5,   defaultVal: 65    },
    ],
    toggles: [
      { id: 'set_heater_enabled',    label: 'Heater Enable' },
      { id: 'cooling_jacket_enable', label: 'Cooling Jacket Loop' },
      { id: 'exhaust_purge_valve',   label: 'Purge Vent Valve' },
    ],
    actions: [
      { id: 'chamber_n2_purge',      label: 'Chamber N₂ Purge',     description: 'Flushes combustion chamber with nitrogen', icon: 'purge' },
      { id: 'reset_emergency_stop',  label: 'Reset Safety Interlock', description: 'Clears emergency stop and resumes operation', icon: 'reset' },
    ],
  },
  'refinery-2': {
    title:   'FLUID & FLOW CONTROL UNIT',
    color:   '#00d4ff',
    dataKey: 'refinery-2',
    modes: [
      { id: 'STEADY',      label: 'STEADY'      },
      { id: 'SURGE_GUARD', label: 'SURGE GUARD' },
      { id: 'DRAIN',       label: 'DRAIN'       },
    ],
    knobs: [
      { id: 'set_flow_rate',      label: 'Flow Setpoint',        unit: 'L/min', min: 20.0, max: 100.0, step: 0.5, defaultVal: 35.0 },
      { id: 'throttle_valve_pos', label: 'Throttle Valve Pos',   unit: '%',     min: 0,    max: 100,   step: 1,   defaultVal: 75   },
      { id: 'backpressure_limit', label: 'Backpressure Limit',   unit: 'bar',   min: 1,    max: 30,    step: 0.5, defaultVal: 14   },
    ],
    toggles: [
      { id: 'set_pump_enabled',    label: 'Pump Enable' },
      { id: 'booster_pump_enable', label: 'Aux Booster Pump' },
      { id: 'recirc_loop_enable',  label: 'Recirculation Bypass' },
    ],
    actions: [
      { id: 'line_flush_sequence', label: 'Line Flush Sequence',  description: 'Executes automated line rinse cycle',   icon: 'purge' },
      { id: 'reset_emergency_stop', label: 'Reset Safety Interlock', description: 'Clears emergency stop and resumes operation', icon: 'reset' },
    ],
  },
};

const TABS = [
  { id: 'overview',  label: 'OVERVIEW',  Icon: Activity  },
  { id: 'controls',  label: 'CONTROLS',  Icon: Settings  },
  { id: 'history',   label: 'HISTORY',   Icon: Clock     },
  { id: 'audit',     label: 'AUDIT',     Icon: FileText  },
];

/* ── Live telemetry mini-cards ─────────────────────────────────────────────── */
function LiveCards({ machineId, telemetry, isOffline, color }) {
  const cfg  = MACHINE_CFG[machineId];
  const data = telemetry?.[machineId] || telemetry?.[cfg?.dataKey] || telemetry?.[machineId.replace('-', '_')] || {};
  const metrics = machineId === 'refinery-1'
    ? [{ label: 'Temperature', value: data.temperature, unit: '°C' }, { label: 'Pressure', value: data.pressure, unit: 'bar' }]
    : [{ label: 'Flow Rate',   value: data.flow_rate,   unit: 'L/min' }];

  return (
    <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
      {metrics.map(m => (
        <div key={m.label} style={{
          flex:         '1 1 110px',
          padding:      '12px',
          background:   'rgba(0, 12, 36, 0.65)',
          border:       `1px solid ${color}18`,
          borderRadius: '8px',
        }}>
          <div style={{ fontFamily: "'Share Tech Mono', monospace", fontSize: '10px', color: 'var(--text-muted)', marginBottom: '6px', letterSpacing: '0.07em' }}>
            {m.label.toUpperCase()}
          </div>
          <div style={{
            fontFamily:  "'Share Tech Mono', monospace",
            fontSize:    '24px',
            color:       isOffline ? 'var(--text-muted)' : color,
            textShadow:  isOffline ? 'none' : `0 0 10px ${color}55`,
            transition:  'color 300ms',
          }}>
            {m.value !== undefined && m.value !== null
              ? (typeof m.value === 'number' ? m.value.toFixed(1) : m.value)
              : '—'}
            <span style={{ fontSize: '12px', color: 'var(--text-muted)', marginLeft: '4px' }}>{m.unit}</span>
          </div>
        </div>
      ))}
    </div>
  );
}

/* ── Section header component ─────────────────────────────────────────────── */
function ControlSectionHeader({ icon: Icon, title, color }) {
  return (
    <div style={{
      display:        'flex',
      alignItems:     'center',
      gap:            '7px',
      fontFamily:     "'Share Tech Mono', monospace",
      fontSize:       '11px',
      letterSpacing:  '0.1em',
      color:          color || 'var(--cyan)',
      paddingBottom:  '6px',
      borderBottom:   `1px solid ${color ? `${color}25` : 'rgba(0,212,255,0.15)'}`,
      marginTop:      '4px',
      marginBottom:   '2px',
    }}>
      {Icon && <Icon size={13} />}
      <span>{title}</span>
    </div>
  );
}

/* ── Main drawer ────────────────────────────────────────────────────────────── */
export default function MachineDetailDrawer({ machineId, telemetry, isOffline, onClose }) {
  const [activeTab,     setActiveTab]     = useState('overview');
  const [pending,       setPending]       = useState(null);   // { controlId, value, unit, type }
  const [toggleStates,  setToggleStates]  = useState({});
  const [currentModes,  setCurrentModes]  = useState({});
  const [controlValues, setControlValues] = useState({});

  const { submit, reset, status: cmdStatus, error: cmdError } = useCommand();
  const cfg = MACHINE_CFG[machineId] || { title: machineId, color: '#00d4ff', dataKey: machineId, knobs: [], toggles: [], actions: [], modes: [] };

  const openDialog = (controlId, value, unit, type = 'knob') =>
    setPending({ controlId, value, unit, type });

  const handleConfirm = async reason => {
    if (!pending) return;
    reset();
    let val = pending.value;
    if (pending.type === 'knob' || pending.type === 'setpoint') {
      val = typeof pending.value === 'number' ? pending.value : parseFloat(pending.value);
      setControlValues(prev => ({ ...prev, [pending.controlId]: val }));
    } else if (pending.type === 'toggle') {
      setToggleStates(prev => ({ ...prev, [pending.controlId]: pending.value === 1 }));
    } else if (pending.type === 'mode') {
      setCurrentModes(prev => ({ ...prev, [machineId]: pending.value }));
    }

    let defaultReason = 'Operator adjustment';
    if (pending.controlId === 'emergency_stop') {
      defaultReason = 'Manual emergency stop triggered from HMI';
    } else if (pending.controlId === 'reset_emergency_stop') {
      defaultReason = 'Operator cleared emergency shutdown';
    } else if (pending.controlId === 'set_temperature') {
      defaultReason = 'Setpoint regulation';
    } else if (pending.controlId === 'set_flow_rate') {
      defaultReason = 'Flow adjustment';
    }

    await submit(machineId, pending.controlId, val, reason || defaultReason);
  };

  const handleDialogClose = () => {
    setPending(null);
    reset();
  };

  return (
    <>
      <motion.aside
        id={`drawer-${machineId}`}
        initial={{ x: '100%' }}
        animate={{ x: 0 }}
        exit={{ x: '100%' }}
        transition={{ type: 'spring', damping: 26, stiffness: 210 }}
        style={{
          position:       'absolute',
          right:          0,
          top:            0,
          bottom:         0,
          width:          '430px',
          maxWidth:       '100%',
          background:     'rgba(0, 8, 24, 0.98)',
          borderLeft:     `1px solid ${cfg.color}28`,
          display:        'flex',
          flexDirection:  'column',
          zIndex:         50,
          backdropFilter: 'blur(22px)',
          boxShadow:      `-6px 0 40px rgba(0,0,0,0.65), inset 1px 0 0 ${cfg.color}12`,
        }}
      >
        {/* ── Header ─────────────────────────────────────────────── */}
        <div style={{
          padding:      '16px 20px',
          borderBottom: `1px solid ${cfg.color}18`,
          display:      'flex',
          alignItems:   'center',
          justifyContent: 'space-between',
          background:   `${cfg.color}04`,
          flexShrink:   0,
        }}>
          <div>
            <div style={{
              fontFamily:    "'Rajdhani', sans-serif",
              fontWeight:    700,
              fontSize:      '19px',
              letterSpacing: '0.16em',
              color:         cfg.color,
              textShadow:    `0 0 14px ${cfg.color}55`,
            }}>
              {machineId.toUpperCase().replace(/-/g, ' ')}
            </div>
            <div style={{
              fontFamily:    "'Share Tech Mono', monospace",
              fontSize:      '10px',
              color:         'var(--text-muted)',
              letterSpacing: '0.08em',
            }}>
              {cfg.title}
            </div>
          </div>
          <button
            id={`drawer-close-${machineId}`}
            onClick={onClose}
            style={{
              background:   'transparent',
              border:       '1px solid rgba(120,168,204,0.2)',
              borderRadius: '6px',
              color:        'var(--text-muted)',
              cursor:       'pointer',
              padding:      '6px',
              display:      'flex',
              alignItems:   'center',
              transition:   'all 200ms',
            }}
          >
            <X size={16} />
          </button>
        </div>

        {/* ── Tab bar ────────────────────────────────────────────── */}
        <div style={{
          display:      'flex',
          borderBottom: `1px solid ${cfg.color}12`,
          flexShrink:   0,
        }}>
          {TABS.map(({ id, label, Icon }) => {
            const active = activeTab === id;
            return (
              <button
                key={id}
                id={`tab-${id}`}
                onClick={() => setActiveTab(id)}
                style={{
                  flex:          1,
                  padding:       '10px 4px',
                  background:    active ? `${cfg.color}07` : 'transparent',
                  border:        'none',
                  borderBottom:  `2px solid ${active ? cfg.color : 'transparent'}`,
                  color:         active ? cfg.color : 'var(--text-muted)',
                  cursor:        'pointer',
                  fontFamily:    "'Share Tech Mono', monospace",
                  fontSize:      '9px',
                  letterSpacing: '0.07em',
                  display:       'flex',
                  flexDirection: 'column',
                  alignItems:    'center',
                  gap:           '4px',
                  transition:    'all 200ms',
                  outline:       'none',
                }}
              >
                <Icon size={13} />
                {label}
              </button>
            );
          })}
        </div>

        {/* ── Tab content ────────────────────────────────────────── */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '18px 16px' }}>

          {/* OVERVIEW */}
          {activeTab === 'overview' && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
              <MachineHealth machineId={machineId} telemetry={telemetry} isOffline={isOffline} />
              <div>
                <div style={{ fontFamily: "'Share Tech Mono', monospace", fontSize: '10px', color: 'var(--text-muted)', letterSpacing: '0.1em', marginBottom: '10px' }}>
                  LIVE TELEMETRY
                </div>
                <LiveCards machineId={machineId} telemetry={telemetry} isOffline={isOffline} color={cfg.color} />
              </div>
            </div>
          )}

          {/* CONTROLS */}
          {activeTab === 'controls' && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '18px' }}>
              {isOffline && (
                <div style={{
                  padding:      '10px 14px',
                  background:   'rgba(255,51,102,0.07)',
                  border:       '1px solid rgba(255,51,102,0.25)',
                  borderRadius: '8px',
                  fontFamily:   "'Share Tech Mono', monospace",
                  fontSize:     '11px',
                  color:        'var(--danger)',
                  letterSpacing: '0.06em',
                }}>
                  ⚠ GATEWAY OFFLINE — CONTROLS DISABLED
                </div>
              )}

              {/* 1. Operating Mode */}
              {cfg.modes && cfg.modes.length > 0 && (
                <div>
                  <ControlSectionHeader icon={Sliders} title="SYSTEM OPERATING MODE" color={cfg.color} />
                  <div style={{ marginTop: '8px' }}>
                    <ModeSelectorControl
                      label="Select Profile"
                      options={cfg.modes}
                      value={currentModes[machineId] || cfg.modes[0].id}
                      disabled={isOffline}
                      color={cfg.color}
                      onChange={(optId) => openDialog('set_operating_mode', optId, '', 'mode')}
                    />
                  </div>
                </div>
              )}

              {/* 2. Process Setpoints & Adjusters */}
              {cfg.knobs && cfg.knobs.length > 0 && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                  <ControlSectionHeader icon={Sliders} title="PROCESS SETPOINTS & TUNING" color={cfg.color} />
                  
                  {/* Rotary knobs */}
                  <div style={{ display: 'flex', justifyContent: 'space-around', flexWrap: 'wrap', gap: '12px', padding: '6px 0' }}>
                    {cfg.knobs.map(k => (
                      <ControlKnob
                        key={k.id}
                        label={k.label}
                        unit={k.unit}
                        min={k.min}
                        max={k.max}
                        value={controlValues[k.id] ?? k.defaultVal ?? k.min}
                        color={cfg.color}
                        disabled={isOffline}
                        onChange={v => openDialog(k.id, v, k.unit, 'knob')}
                      />
                    ))}
                  </div>

                  {/* Precise numeric inputs */}
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                    {cfg.knobs.map(k => (
                      <SetpointInput
                        key={`sp-${k.id}`}
                        label={k.label}
                        unit={k.unit}
                        min={k.min}
                        max={k.max}
                        step={k.step}
                        disabled={isOffline}
                        onChange={v => openDialog(k.id, v, k.unit, 'setpoint')}
                      />
                    ))}
                  </div>
                </div>
              )}

              {/* 3. Discrete Actuators & Switches */}
              {cfg.toggles && cfg.toggles.length > 0 && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                  <ControlSectionHeader icon={ToggleLeft} title="DISCRETE ACTUATORS & VALVES" color={cfg.color} />
                  {cfg.toggles.map(t => (
                    <ToggleControl
                      key={t.id}
                      label={t.label}
                      value={toggleStates[t.id] ?? false}
                      disabled={isOffline}
                      onToggle={v => openDialog(t.id, v ? 1 : 0, '', 'toggle')}
                    />
                  ))}
                </div>
              )}

              {/* 4. Automated Procedures & Operational Actions */}
              {cfg.actions && cfg.actions.length > 0 && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                  <ControlSectionHeader icon={PlayCircle} title="PROCEDURES & ROUTINES" color={cfg.color} />
                  {cfg.actions.map(act => (
                    <ActionTriggerControl
                      key={act.id}
                      id={act.id}
                      label={act.label}
                      description={act.description}
                      icon={act.icon}
                      disabled={isOffline}
                      color={cfg.color}
                      onTrigger={(id, val, reason) => openDialog(id, val, '', 'action')}
                    />
                  ))}
                </div>
              )}

              {/* 5. Emergency Isolation */}
              <div>
                <ControlSectionHeader icon={ShieldAlert} title="SAFETY & EMERGENCY ISOLATION" color="var(--danger)" />
                {(() => {
                  const mData = telemetry?.[machineId] || telemetry?.[cfg?.dataKey] || telemetry?.[machineId.replace('-', '_')] || {};
                  const mStatus = getMachineStatus(isOffline ? { status: 'offline' } : mData);
                  const isStopped = mStatus.label === 'STOPPED';

                  return (
                    <div style={{ marginTop: '10px', display: 'flex', flexDirection: 'column', gap: '8px' }}>
                      {isStopped && (
                        <div style={{
                          padding:      '10px 12px',
                          background:   'rgba(255, 51, 102, 0.1)',
                          border:       '1px solid rgba(255, 51, 102, 0.35)',
                          borderRadius: '6px',
                          fontFamily:   "'Share Tech Mono', monospace",
                          fontSize:     '11px',
                          color:        'var(--danger)',
                          letterSpacing: '0.05em',
                        }}>
                          ⚠ MACHINE EMERGENCY STOPPED — RESUME TO RESTORE OPERATION
                        </div>
                      )}
                      <EmergencyStop
                        machineId={machineId}
                        disabled={isOffline}
                        isStopped={isStopped}
                        onTrigger={(cmd, val, reason) => openDialog(cmd, val, '', 'emergency')}
                      />
                    </div>
                  );
                })()}
              </div>
            </div>
          )}

          {/* HISTORY */}
          {activeTab === 'history' && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
              <div style={{ fontFamily: "'Share Tech Mono', monospace", fontSize: '10px', color: 'var(--text-muted)', letterSpacing: '0.1em' }}>
                TELEMETRY HISTORY — LAST 30 MIN
              </div>
              <TrendChart machineId={machineId} />
            </div>
          )}

          {/* AUDIT */}
          {activeTab === 'audit' && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
              <div style={{ fontFamily: "'Share Tech Mono', monospace", fontSize: '10px', color: 'var(--text-muted)', letterSpacing: '0.1em' }}>
                CONTROL AUDIT LOG
              </div>
              <ControlAuditList machineId={machineId} />
            </div>
          )}

        </div>
      </motion.aside>

      {/* ── Command confirm dialog ─────────────────────────────────── */}
      <CommandConfirmDialog
        open={!!pending}
        onClose={handleDialogClose}
        onConfirm={handleConfirm}
        commandStatus={cmdStatus}
        commandError={cmdError}
        machineId={machineId}
        command={pending?.controlId}
        value={pending?.value}
        unit={pending?.unit}
      />
    </>
  );
}

