import { useState, useEffect, useRef, useCallback } from 'react';
import { fetchAllModbus, fetchHealth } from '../api/gateway';

const POLL_INTERVAL = 2000;

export function useTelemetry() {
  const [data,        setData]        = useState({});
  const [health,      setHealth]      = useState({ status: 'connecting', plc_1: 'checking', plc_2: 'checking' });
  const [lastUpdated, setLastUpdated] = useState(() => new Date());
  const [isOffline,   setIsOffline]   = useState(false);
  const [isDemoMode,  setIsDemoMode]  = useState(false);
  const [error,       setError]       = useState(null);
  const timerRef      = useRef(null);
  const failCountRef  = useRef(0);

  const poll = useCallback(async () => {
    try {
      const [modbusData, healthData] = await Promise.all([
        fetchAllModbus(),
        fetchHealth().catch(() => ({ status: 'unknown', plc_1: 'unknown', plc_2: 'unknown' })),
      ]);

      failCountRef.current = 0;

      // Normalize telemetry so both hyphen and underscore keys exist
      const normalized = { ...modbusData };
      if (normalized['refinery-1'] && !normalized['refinery_1']) {
        normalized['refinery_1'] = normalized['refinery-1'];
      } else if (normalized['refinery_1'] && !normalized['refinery-1']) {
        normalized['refinery-1'] = normalized['refinery_1'];
      }
      if (normalized['refinery-2'] && !normalized['refinery_2']) {
        normalized['refinery_2'] = normalized['refinery-2'];
      } else if (normalized['refinery_2'] && !normalized['refinery-2']) {
        normalized['refinery-2'] = normalized['refinery_2'];
      }

      setData(normalized);
      setHealth(typeof healthData === 'string' ? { status: healthData.trim(), plc_1: 'connected', plc_2: 'connected' } : healthData);
      setLastUpdated(new Date());
      setIsOffline(false);
      setIsDemoMode(false);
      setError(null);
    } catch (err) {
      failCountRef.current += 1;
      setError(err.message);
      setIsOffline(true);
      setIsDemoMode(false);
    }
  }, []);

  useEffect(() => {
    poll();

    const startPolling = () => {
      if (!timerRef.current) {
        timerRef.current = setInterval(poll, POLL_INTERVAL);
      }
    };
    const stopPolling = () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
    };
    const handleVisibilityChange = () => {
      if (document.hidden) {
        stopPolling();
      } else {
        poll();
        startPolling();
      }
    };

    startPolling();
    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      stopPolling();
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [poll]);

  return { data, health, lastUpdated, isOffline, isDemoMode, error };
}

