import React from 'react';

export default function ToggleControl({
  label, value, disabled, onToggle,
}) {
  return (
    <div style={{
      display:     'flex',
      alignItems:  'center',
      justifyContent: 'space-between',
      gap:         '12px',
      padding:     '10px 12px',
      background:  'rgba(0, 12, 32, 0.55)',
      border:      '1px solid rgba(0,212,255,0.08)',
      borderRadius: '8px',
    }}>
      <span style={{
        fontFamily:    "'Share Tech Mono', monospace",
        fontSize:      '12px',
        color:         'var(--text-secondary)',
        letterSpacing: '0.06em',
        textTransform: 'uppercase',
        flex:          1,
      }}>
        {label}
      </span>

      <button
        role="switch"
        aria-checked={value}
        onClick={() => !disabled && onToggle(!value)}
        disabled={disabled}
        style={{
          position:     'relative',
          width:        '50px',
          height:       '26px',
          borderRadius: '13px',
          border:       `1px solid ${value ? 'rgba(0,212,255,0.7)' : 'rgba(0,212,255,0.2)'}`,
          background:   value ? 'rgba(0,212,255,0.18)' : 'rgba(0,10,30,0.8)',
          cursor:       disabled ? 'not-allowed' : 'pointer',
          transition:   'all 280ms ease',
          opacity:      disabled ? 0.4 : 1,
          outline:      'none',
          boxShadow:    value ? '0 0 14px rgba(0,212,255,0.35)' : 'none',
          flexShrink:   0,
        }}
      >
        <span style={{
          position:     'absolute',
          top:          '3px',
          left:         value ? '25px' : '3px',
          width:        '18px',
          height:       '18px',
          borderRadius: '50%',
          background:   value ? '#00d4ff' : 'rgba(0,212,255,0.45)',
          boxShadow:    value ? '0 0 8px #00d4ff' : 'none',
          transition:   'all 280ms ease',
        }} />
      </button>

      <span style={{
        fontFamily:    "'Share Tech Mono', monospace",
        fontSize:      '11px',
        color:         value ? 'var(--cyan)' : 'var(--text-muted)',
        minWidth:      '28px',
        textAlign:     'right',
        transition:    'color 200ms',
      }}>
        {value ? 'ON' : 'OFF'}
      </span>
    </div>
  );
}
