import API_BASE_URL from './config';

async function request(path, options = {}) {
  const res = await fetch(`${API_BASE_URL}${path}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      'X-Operator': 'operator-console',
      ...options.headers,
    },
  });
  if (!res.ok) {
    const text = await res.text().catch(() => '');
    throw new Error(`${res.status} ${res.statusText}${text ? ': ' + text : ''}`);
  }
  const contentType = res.headers.get('content-type') || '';
  if (contentType.includes('application/json')) {
    return res.json();
  }
  const text = await res.text();
  return { status: text.trim() };
}

// ── Modbus telemetry ──────────────────────────────────────────────────────────
export const fetchAllModbus = () => request('/api/modbus');
export const fetchRefinery1 = () => request('/api/modbus/refinery-1');
export const fetchRefinery2 = () => request('/api/modbus/refinery-2');
export const fetchHealth = () => request('/health');

// ── SCADA machine metadata ────────────────────────────────────────────────────
export const fetchMachines = () => request('/api/scada/machines');

// ── Commands ──────────────────────────────────────────────────────────────────
export const postCommand = (machineId, { command, value, reason }) => {
  const payload = { command };
  if (value !== undefined && value !== null) {
    payload.value = typeof value === 'number' ? value : parseFloat(value);
  }
  if (reason) {
    payload.reason = reason;
  } else if (command === 'emergency_stop') {
    payload.reason = 'Manual emergency stop triggered from HMI';
  } else if (command === 'reset_emergency_stop') {
    payload.reason = 'Operator cleared emergency shutdown';
  } else if (command === 'set_temperature') {
    payload.reason = 'Setpoint regulation';
  } else if (command === 'set_flow_rate') {
    payload.reason = 'Flow adjustment';
  } else {
    payload.reason = 'Operator adjustment';
  }

  return request(`/api/scada/machines/${machineId}/commands`, {
    method: 'POST',
    headers: {
      'X-Operator': 'operator-console',
    },
    body: JSON.stringify(payload),
  });
};

export const pollCommand = (commandId) =>
  request(`/api/scada/commands/${commandId}`);

// ── History ───────────────────────────────────────────────────────────────────
export const fetchHistory = (machineId, metric, from, to) => {
  const params = new URLSearchParams({ metric });
  if (from) params.set('from', from);
  if (to) params.set('to', to);
  return request(`/api/scada/machines/${machineId}/history?${params}`);
};

// ── Alarms ────────────────────────────────────────────────────────────────────
export const fetchAlarms = () => request('/api/scada/alarms');
export const acknowledgeAlarm = (alarmId, note) =>
  request(`/api/scada/alarms/${alarmId}/acknowledge`, {
    method: 'POST',
    body: JSON.stringify({ note }),
  });

// ── Audit ─────────────────────────────────────────────────────────────────────
export const fetchAudit = (machineId) => {
  const params = machineId ? `?machine_id=${machineId}` : '';
  return request(`/api/scada/audit${params}`);
};
