import React from 'react';
import { Activity, Bell } from 'lucide-react';
import StatusBadge from '../shared/StatusBadge';
import LastUpdated from './LastUpdated';
import ReducedMotionToggle from '../shared/ReducedMotionToggle';

export default function ConnectionBanner({
  health, lastUpdated, isOffline, isDemoMode, alarmCount,
}) {
  const gwStatus = isOffline
    ? 'offline'
    : isDemoMode
    ? 'online'
    : (health?.status || 'unknown');

  const borderColor = isOffline
    ? 'rgba(255, 51, 102, 0.25)'
    : isDemoMode
    ? 'rgba(255, 215, 0, 0.18)'
    : 'rgba(0, 212, 255, 0.12)';

  return (
    <header style={{
      display:          'flex',
      alignItems:       'center',
      justifyContent:   'space-between',
      padding:          '0 20px',
      height:           '48px',
      background:       'rgba(0, 8, 22, 0.96)',
      borderBottom:     `1px solid ${borderColor}`,
      backdropFilter:   'blur(16px)',
      flexShrink:       0,
      zIndex:           100,
      position:         'relative',
    }}>

      {/* ── Left: logo + gateway status ─────────────────── */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '14px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <Activity size={17} color="var(--cyan)" style={{ filter: 'drop-shadow(0 0 6px var(--cyan))' }} />
          <span style={{
            fontFamily:    "'Rajdhani', sans-serif",
            fontWeight:    700,
            fontSize:      '17px',
            letterSpacing: '0.18em',
            color:         'var(--cyan)',
            textShadow:    '0 0 14px rgba(0,212,255,0.5)',
          }}>SCADA</span>
          <span style={{
            fontFamily:    "'Rajdhani', sans-serif",
            fontWeight:    400,
            fontSize:      '12px',
            letterSpacing: '0.12em',
            color:         'var(--text-muted)',
          }}>REFINERY CONTROL</span>
        </div>

        <div style={{ width: '1px', height: '20px', background: 'var(--border-glow)' }} />
        <StatusBadge status={gwStatus} size="sm" />
      </div>

      {/* ── Centre: PLC states + last updated ───────────── */}
      <div style={{
        display:    'flex',
        alignItems: 'center',
        gap:        '20px',
        fontFamily: "'Share Tech Mono', monospace",
        fontSize:   '11px',
        color:      'var(--text-muted)',
      }}>
        {health && (
          <>
            <span>
              PLC-1:&nbsp;
              <span style={{ color: health.plc_1 === 'connected' ? 'var(--cyan)' : 'var(--danger)' }}>
                {(health.plc_1 || 'UNKNOWN').toUpperCase()}
              </span>
            </span>
            <span style={{ color: 'var(--text-muted)' }}>|</span>
            <span>
              PLC-2:&nbsp;
              <span style={{ color: health.plc_2 === 'connected' ? 'var(--cyan)' : 'var(--danger)' }}>
                {(health.plc_2 || 'UNKNOWN').toUpperCase()}
              </span>
            </span>
            <span style={{ color: 'var(--text-muted)' }}>|</span>
          </>
        )}
        <LastUpdated lastUpdated={lastUpdated} isOffline={isOffline} />
      </div>

      {/* ── Right: status badge + alarm count + controls ────────────────── */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
        {isOffline && (
          <div style={{
            display:       'flex',
            alignItems:    'center',
            gap:           '5px',
            fontFamily:    "'Share Tech Mono', monospace",
            fontSize:      '10px',
            letterSpacing: '0.1em',
            color:         'var(--danger)',
            background:    'rgba(255,51,102,0.1)',
            border:        '1px solid rgba(255,51,102,0.4)',
            borderRadius:  '3px',
            padding:       '3px 8px',
          }}>
            ⚠ GATEWAY OFFLINE
          </div>
        )}
        {isDemoMode && (
          <div style={{
            display:       'flex',
            alignItems:    'center',
            gap:           '5px',
            fontFamily:    "'Share Tech Mono', monospace",
            fontSize:      '10px',
            letterSpacing: '0.1em',
            color:         'var(--amber)',
            background:    'rgba(255,215,0,0.08)',
            border:        '1px solid rgba(255,215,0,0.3)',
            borderRadius:  '3px',
            padding:       '3px 8px',
          }}>
            ⚡ DEMO SIMULATION
          </div>
        )}
        {alarmCount > 0 && (
          <div style={{
            display:    'flex',
            alignItems: 'center',
            gap:        '5px',
            fontFamily: "'Share Tech Mono', monospace",
            fontSize:   '12px',
            color:      'var(--amber)',
            animation:  'danger-pulse 2s ease-in-out infinite',
          }}>
            <Bell size={13} />
            {alarmCount} ALARM{alarmCount !== 1 ? 'S' : ''}
          </div>
        )}
        <ReducedMotionToggle />
      </div>
    </header>
  );
}
