import React, { useState } from 'react';
import {
  AreaChart, Area, XAxis, YAxis,
  CartesianGrid, Tooltip, ResponsiveContainer,
} from 'recharts';
import { useHistory } from '../../hooks/useHistory';
import LoadingState from '../shared/LoadingState';

const METRICS = {
  'refinery-1': [
    { key: 'temperature', label: 'Temperature', unit: '°C',    color: '#00d4ff' },
    { key: 'pressure',    label: 'Pressure',    unit: 'bar',   color: '#00d4ff' },
  ],
  'refinery-2': [
    { key: 'flow_rate',   label: 'Flow Rate',   unit: 'L/min', color: '#00d4ff' },
  ],
};

function CustomTooltip({ active, payload }) {
  if (!active || !payload?.length) return null;
  const p = payload[0];
  return (
    <div style={{
      background:   'rgba(0, 8, 22, 0.96)',
      border:       '1px solid rgba(0,212,255,0.28)',
      borderRadius: '6px',
      padding:      '8px 12px',
      fontFamily:   "'Share Tech Mono', monospace",
      fontSize:     '11px',
    }}>
      <div style={{ color: 'var(--text-muted)', marginBottom: '4px' }}>
        {new Date(p.payload.time).toLocaleTimeString('en-US', { hour12: false })}
      </div>
      <div style={{ color: p.color }}>
        {p.value?.toFixed(2)} {p.payload.unit}
      </div>
    </div>
  );
}

export default function TrendChart({ machineId }) {
  const metrics       = METRICS[machineId] || [];
  const [active, setActive] = useState(metrics[0]?.key || '');
  const metric        = metrics.find(m => m.key === active) || metrics[0];
  const { samples, loading } = useHistory(machineId, active);

  if (!metric) return null;

  const chartData = samples.map(s => ({
    time:  new Date(s.timestamp).getTime(),
    value: s.value,
    unit:  metric.unit,
  }));

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      {/* Metric selector */}
      {metrics.length > 1 && (
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
          {metrics.map(m => (
            <button
              key={m.key}
              onClick={() => setActive(m.key)}
              style={{
                background:    active === m.key ? `${m.color}18` : 'transparent',
                border:        `1px solid ${active === m.key ? m.color : 'rgba(0,212,255,0.18)'}`,
                borderRadius:  '4px',
                color:         active === m.key ? m.color : 'var(--text-muted)',
                padding:       '4px 11px',
                fontSize:      '10px',
                cursor:        'pointer',
                fontFamily:    "'Share Tech Mono', monospace",
                letterSpacing: '0.06em',
                transition:    'all 200ms',
              }}
            >
              {m.label.toUpperCase()}
            </button>
          ))}
        </div>
      )}

      {loading ? (
        <LoadingState message="Loading history..." />
      ) : chartData.length === 0 ? (
        <div style={{
          height:         '130px',
          display:        'flex',
          alignItems:     'center',
          justifyContent: 'center',
          fontFamily:     "'Share Tech Mono', monospace",
          fontSize:       '11px',
          color:          'var(--text-muted)',
          border:         '1px dashed rgba(0,212,255,0.12)',
          borderRadius:   '8px',
        }}>
          NO HISTORY DATA
        </div>
      ) : (
        <div style={{ height: '150px' }}>
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={chartData} margin={{ top: 4, right: 4, bottom: 0, left: -24 }}>
              <defs>
                <linearGradient id={`trend-grad-${machineId}`} x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%"  stopColor={metric.color} stopOpacity={0.28} />
                  <stop offset="95%" stopColor={metric.color} stopOpacity={0.02} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(0,212,255,0.06)" />
              <XAxis
                dataKey="time"
                type="number"
                scale="time"
                domain={['auto', 'auto']}
                tickFormatter={v =>
                  new Date(v).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false })
                }
                tick={{ fontFamily: "'Share Tech Mono', monospace", fontSize: 9, fill: 'rgba(120,168,204,0.7)' }}
                tickLine={false}
                axisLine={{ stroke: 'rgba(0,212,255,0.1)' }}
              />
              <YAxis
                tick={{ fontFamily: "'Share Tech Mono', monospace", fontSize: 9, fill: 'rgba(120,168,204,0.7)' }}
                tickLine={false}
                axisLine={{ stroke: 'rgba(0,212,255,0.1)' }}
              />
              <Tooltip content={<CustomTooltip />} />
              <Area
                type="monotone"
                dataKey="value"
                stroke={metric.color}
                strokeWidth={2}
                fill={`url(#trend-grad-${machineId})`}
                dot={false}
                style={{ filter: `drop-shadow(0 0 4px ${metric.color}55)` }}
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      )}
    </div>
  );
}
