import React, { useState } from 'react';
import { AnimatePresence } from 'framer-motion';
import { WifiOff } from 'lucide-react';
import ConnectionBanner from './ConnectionBanner';
import AlarmRail from './AlarmRail';
import HologramScene from '../scene/HologramScene';
import MachineDetailDrawer from '../detail/MachineDetailDrawer';
import { useTelemetry } from '../../hooks/useTelemetry';
import { useAlarms } from '../../hooks/useAlarms';

export default function ScadaLayout() {
  const [selected, setSelected] = useState(null);
  const { data, health, lastUpdated, isOffline, isDemoMode } = useTelemetry();
  const { alarms, acknowledge } = useAlarms();

  const activeAlarms = alarms.filter(a => a.status !== 'acknowledged');

  return (
    <div style={{
      display:       'flex',
      flexDirection: 'column',
      height:        '100%',
      overflow:      'hidden',
    }}>
      <ConnectionBanner
        health={health}
        lastUpdated={lastUpdated}
        isOffline={isOffline}
        isDemoMode={isDemoMode}
        alarmCount={activeAlarms.length}
      />

      {isOffline && (
        <div style={{
          background:    'rgba(255, 51, 102, 0.18)',
          borderBottom:  '1px solid rgba(255, 51, 102, 0.6)',
          color:         '#ff3366',
          padding:       '6px 16px',
          textAlign:     'center',
          fontFamily:    "'Share Tech Mono', monospace",
          fontSize:      '11px',
          letterSpacing: '0.12em',
          display:       'flex',
          alignItems:    'center',
          justifyContent:'center',
          gap:           '8px',
          zIndex:        102,
        }}>
          <WifiOff size={14} />
          <span>GATEWAY CONNECTION LOST — SCADA SYSTEM OFFLINE. RECONNECTING TO REAL PIPELINE...</span>
        </div>
      )}

      <AlarmRail alarms={alarms} onAcknowledge={acknowledge} />

      {/* Main scene + drawer */}
      <div style={{ position: 'relative', flex: 1, overflow: 'hidden' }}>
        <HologramScene
          telemetry={data}
          selectedMachine={selected}
          onSelectMachine={setSelected}
          isOffline={isOffline}
          isDemoMode={isDemoMode}
          alarms={alarms}
        />

        <AnimatePresence>
          {selected && (
            <MachineDetailDrawer
              key={selected}
              machineId={selected}
              telemetry={data}
              isOffline={isOffline}
              onClose={() => setSelected(null)}
            />
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}
