import React from 'react';

export default function ModeSelectorControl({
  label,
  options = [],
  value,
  disabled,
  onChange,
  color = 'var(--cyan)',
}) {
  return (
    <div style={{
      display:        'flex',
      flexDirection:  'column',
      gap:            '8px',
      padding:        '12px',
      background:     'rgba(0, 12, 32, 0.55)',
      border:         '1px solid rgba(0, 212, 255, 0.08)',
      borderRadius:   '8px',
    }}>
      <div style={{
        display:        'flex',
        justifyContent: 'space-between',
        alignItems:     'center',
      }}>
        <span style={{
          fontFamily:    "'Share Tech Mono', monospace",
          fontSize:      '11px',
          color:         'var(--text-secondary)',
          letterSpacing: '0.08em',
          textTransform: 'uppercase',
        }}>
          {label}
        </span>
        <span style={{
          fontFamily:    "'Share Tech Mono', monospace",
          fontSize:      '10px',
          color:         color,
          padding:       '2px 6px',
          background:    'rgba(0, 212, 255, 0.07)',
          borderRadius:  '4px',
          border:        `1px solid ${color}33`,
        }}>
          ACTIVE: {value || options[0]?.id || 'N/A'}
        </span>
      </div>

      <div style={{
        display:      'grid',
        gridTemplateColumns: `repeat(${options.length}, 1fr)`,
        gap:          '6px',
      }}>
        {options.map((opt) => {
          const isSelected = (value ?? options[0]?.id) === opt.id;
          return (
            <button
              key={opt.id}
              type="button"
              disabled={disabled}
              onClick={() => !disabled && onChange && onChange(opt.id, opt.label)}
              style={{
                padding:       '8px 4px',
                background:    isSelected ? `${color}22` : 'rgba(0, 8, 20, 0.6)',
                border:        `1px solid ${isSelected ? color : 'rgba(120, 168, 204, 0.15)'}`,
                borderRadius:  '5px',
                color:         isSelected ? '#ffffff' : 'var(--text-muted)',
                fontFamily:    "'Share Tech Mono', monospace",
                fontSize:      '10px',
                letterSpacing: '0.06em',
                cursor:        disabled ? 'not-allowed' : 'pointer',
                transition:    'all 200ms ease',
                boxShadow:     isSelected ? `0 0 12px ${color}44` : 'none',
                opacity:       disabled ? 0.4 : 1,
                outline:       'none',
              }}
            >
              {opt.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}
