import React, { useState } from 'react';
import AlarmBeacon from './AlarmBeacon';
import StatusBadge, { getMachineStatus } from '../shared/StatusBadge';
import TelemetryLabel from './TelemetryLabel';

const MACHINE_META = {
  'refinery-1': {
    title:    'REFINERY 1',
    subtitle: 'HEATER UNIT',
    image:    '/r1_heater.jpg',
    color:    '#00d4ff',
    dataKey:  'refinery_1',
    metrics:  [
      { key: 'temperature', label: 'TEMP',     unit: '°C'  },
      { key: 'pressure',    label: 'PRESSURE', unit: 'bar' },
    ],
  },
  'refinery-2': {
    title:    'REFINERY 2',
    subtitle: 'FLOW UNIT',
    image:    '/r2_flow.jpg',
    color:    '#00d4ff',
    dataKey:  'refinery_2',
    metrics:  [
      { key: 'flow_rate', label: 'FLOW RATE', unit: 'L/min' },
    ],
  },
};

export default function MachineNode({
  machineId, telemetry, isSelected, isOffline, hasAlarm, alarmSeverity = 'warning', onClick,
}) {
  const [hovered, setHovered] = useState(false);
  const meta    = MACHINE_META[machineId] || { title: machineId, subtitle: '', image: null, color: '#00d4ff', dataKey: machineId, metrics: [] };
  const { title, subtitle, image, color, dataKey, metrics } = meta;
  const data    = telemetry?.[machineId] || telemetry?.[dataKey] || telemetry?.[machineId.replace('-', '_')] || {};
  const isRight = machineId === 'refinery-2';

  const statusInfo = getMachineStatus(isOffline ? { status: 'offline' } : data);
  const isStopped = statusInfo.label === 'STOPPED';
  const isOfflineState = isOffline || statusInfo.label === 'OFFLINE';
  const isSevere    = isOfflineState || isStopped || alarmSeverity === 'critical' || alarmSeverity === 'severe';
  const glowColor   = isStopped ? '#ff3366' : isSevere ? '#ff3366' : hasAlarm ? '#ffd700' : color;
  const borderColor = isSevere
    ? 'rgba(255,51,102,0.8)'
    : hasAlarm
    ? 'rgba(255,215,0,0.8)'
    : isSelected
    ? color
    : `${color}28`;

  return (
    <div
      id={`machine-${machineId}`}
      role="button"
      tabIndex={0}
      aria-pressed={isSelected}
      onClick={onClick}
      onKeyDown={e => e.key === 'Enter' && onClick()}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        position:   'relative',
        flex:       '0 0 38%',
        height:     '100%',
        cursor:     'pointer',
        outline:    'none',
        overflow:   'hidden',
        borderRight: !isRight ? `1px solid ${borderColor}` : 'none',
        borderLeft:   isRight ? `1px solid ${borderColor}` : 'none',
        transition:  'border-color 400ms',
      }}
    >
      {/* ── Full-bleed image ─────────────────────────────────── */}
      <img
        src={image}
        alt={title}
        style={{
          position:   'absolute',
          inset:      0,
          width:      '100%',
          height:     '100%',
          objectFit:  'cover',
          objectPosition: 'center',
          transform:  hovered ? 'scale(1.06)' : 'scale(1)',
          transition: 'transform 700ms cubic-bezier(0.25, 0.46, 0.45, 0.94)',
          filter:     isOffline
            ? 'brightness(0.5) saturate(0.35)'
            : hovered
            ? `brightness(1.35) contrast(1.12) saturate(1.15) drop-shadow(0 0 35px ${glowColor})`
            : 'brightness(1.22) contrast(1.08) saturate(1.05)',
          opacity:    1,
          display:    'block',
        }}
      />

      {/* ── Colour tint overlay ── */}
      <div style={{
        position:      'absolute',
        inset:         0,
        background:    hovered
          ? `radial-gradient(ellipse 80% 70% at 50% 50%, ${glowColor}15 0%, transparent 70%)`
          : `linear-gradient(to top, rgba(0,5,14,0.65) 0%, rgba(0,5,14,0.02) 45%, rgba(0,5,14,0.3) 100%)`,
        transition:    'background 500ms',
        pointerEvents: 'none',
        zIndex:        2,
      }} />

      {/* ── Glow border pulse on hover ── */}
      {hovered && (
        <div style={{
          position:      'absolute',
          inset:         0,
          border:        `2px solid ${glowColor}`,
          boxShadow:     `inset 0 0 60px ${glowColor}20, 0 0 40px ${glowColor}30`,
          pointerEvents: 'none',
          zIndex:        3,
          animation:     'hologram-pulse 2s ease-in-out infinite',
        }} />
      )}

      {/* ── Selected state indicator ── */}
      {isSelected && !hovered && (
        <div style={{
          position:      'absolute',
          inset:         0,
          border:        `2px solid ${color}`,
          boxShadow:     `inset 0 0 40px ${color}15`,
          pointerEvents: 'none',
          zIndex:        3,
        }} />
      )}

      {/* ── Alarm beacon ── */}
      <div style={{ position: 'absolute', top: '16px', right: '16px', zIndex: 10 }}>
        <AlarmBeacon active={hasAlarm} severity={alarmSeverity} />
      </div>

      {/* ── Top label ── */}
      <div style={{
        position:   'absolute',
        top:        0,
        left:       0,
        right:      0,
        padding:    '20px 24px 40px',
        background: 'linear-gradient(to bottom, rgba(0,5,14,0.7) 0%, transparent 100%)',
        zIndex:     5,
      }}>
        <div style={{
          fontFamily:    "'Rajdhani', sans-serif",
          fontWeight:    700,
          fontSize:      '22px',
          letterSpacing: '0.2em',
          color:         hovered ? glowColor : 'rgba(255,255,255,0.9)',
          textShadow:    hovered ? `0 0 20px ${glowColor}, 0 0 40px ${glowColor}80` : '0 2px 8px rgba(0,0,0,0.8)',
          transition:    'color 300ms, text-shadow 300ms',
          lineHeight:    1.1,
        }}>
          {title}
        </div>
        <div style={{
          fontFamily:    "'Share Tech Mono', monospace",
          fontSize:      '11px',
          color:         'rgba(120,168,204,0.8)',
          letterSpacing: '0.12em',
          marginTop:     '4px',
        }}>
          {subtitle}
        </div>
      </div>

      {/* ── Bottom telemetry strip ── */}
      <div style={{
        position:   'absolute',
        bottom:     '40px',           /* above utility rail */
        left:       0,
        right:      0,
        padding:    '28px 24px 20px',
        background: 'linear-gradient(to top, rgba(0,5,14,0.85) 0%, rgba(0,5,14,0.4) 50%, transparent 100%)',
        zIndex:     5,
        transform:  hovered ? 'translateY(0)' : 'translateY(8px)',
        opacity:    hovered || isSelected ? 1 : 0.75,
        transition: 'transform 400ms ease, opacity 400ms ease',
      }}>
        {/* Status badge */}
        <div style={{ marginBottom: '14px' }}>
          <StatusBadge status={statusInfo.status} label={statusInfo.label} size="sm" />
        </div>

        {/* Metric values */}
        <div style={{ display: 'flex', gap: '28px', flexWrap: 'wrap' }}>
          {metrics.map(m => (
            <TelemetryLabel
              key={m.key}
              label={m.label}
              value={data[m.key]}
              unit={m.unit}
              isOffline={isOffline}
            />
          ))}
        </div>

        {/* Click prompt */}
        <div style={{
          marginTop:     '14px',
          fontFamily:    "'Share Tech Mono', monospace",
          fontSize:      '10px',
          letterSpacing: '0.14em',
          color:         hovered ? glowColor : 'rgba(120,168,204,0.4)',
          transition:    'color 300ms',
        }}>
          {hovered ? '▶ CLICK TO OPEN CONTROL PANEL' : 'HOVER TO INSPECT'}
        </div>
      </div>

      {/* Scanlines */}
      <div style={{
        position:      'absolute',
        inset:         0,
        background:    'repeating-linear-gradient(0deg, transparent, transparent 3px, rgba(0,0,0,0.025) 3px, rgba(0,0,0,0.025) 4px)',
        pointerEvents: 'none',
        zIndex:        4,
      }} />
    </div>
  );
}
