import React, { useState, useEffect } from 'react';
import { Clock } from 'lucide-react';

function formatAge(date) {
  if (!date) return 'NEVER';
  const secs = Math.floor((Date.now() - date.getTime()) / 1000);
  if (secs < 5)  return 'JUST NOW';
  if (secs < 60) return `${secs}S AGO`;
  return `${Math.floor(secs / 60)}M AGO`;
}

export default function LastUpdated({ lastUpdated, isOffline }) {
  const [, setTick] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setTick(t => t + 1), 1000);
    return () => clearInterval(id);
  }, []);

  const age   = lastUpdated ? Math.floor((Date.now() - lastUpdated.getTime()) / 1000) : null;
  const stale = age !== null && age > 10;
  const color = stale || isOffline ? 'var(--orange)' : 'var(--text-muted)';

  return (
    <div style={{
      display:       'flex',
      alignItems:    'center',
      gap:           '5px',
      fontFamily:    "'Share Tech Mono', monospace",
      fontSize:      '11px',
      color,
      transition:    'color 400ms',
    }}>
      <Clock size={11} />
      <span>UPDATED {formatAge(lastUpdated)}</span>
      {stale && <span style={{ color: 'var(--orange)' }}>⚠</span>}
    </div>
  );
}
